import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/OnPositionEmbeddingsInBERT.html","title":"OnPositionEmbeddingsInBERT","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.83,"words":250},"filePathRelative":"OnPositionEmbeddingsInBERT.md"}`),a={name:`OnPositionEmbeddingsInBERT.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="onpositionembeddingsinbert" tabindex="-1"><a class="header-anchor" href="#onpositionembeddingsinbert"><span>OnPositionEmbeddingsInBERT</span></a></h1><p><a href="./BERT.html">BERT</a>にいろんな<a href="./PositionEmbeddings.html">PositionEmbeddings</a>を試してみて結果を見る<a href="./論文.html">論文</a>。</p><ul><li><a href="https://openreview.net/forum?id=onxoVA9FxMw" target="_blank" rel="noopener noreferrer">On Position Embeddings in BERT - OpenReview</a></li></ul><p><a href="./WhatDoPositionEmbeddingsLearn.html">WhatDoPositionEmbeddingsLearn</a>が微妙だったので他のも見てみようと思って見かけた論文。 いろいろなPEに対して3つの数学的性質がどのくらい満たされているのかを調べたり、BERTにつなげてSQuADやGLUEがどのくらいのスコアになるかを調べたりする。</p><h2 id="span-prediction" tabindex="-1"><a class="header-anchor" href="#span-prediction"><span>Span prediction</span></a></h2><p><a href="./SQuAD.html">SQuAD</a>に詳細があるように、パッセージの一部が回答になるようなQ and A。</p><h2 id="調べる対象のposition-embeddings" tabindex="-1"><a class="header-anchor" href="#調べる対象のposition-embeddings"><span>調べる対象のPosition Embeddings</span></a></h2><ul><li>Fully learnable APE （<a href="./ConvS2S.html">ConvS2S</a>のもの）</li><li>Fixed sinusoidal APE (<a href="./Transformer.html">Transformer</a>のもの)</li><li>Learnable sinusoidal APE (この論文が提案するもの、sinusoidalのwを学習）</li><li>Fully learnable RPE (relativeな奴だけを入れる奴）</li><li>Fixed sinusoidal RPE</li><li>Learnable sinusoidal RPE (この論文が提案するもの、sinusoidalのwを学習）</li></ul><h2 id="検討する性質" tabindex="-1"><a class="header-anchor" href="#検討する性質"><span>検討する性質</span></a></h2><ul><li>Monotonicity</li><li>Translation Invariance</li><li>Symmetry</li></ul><p>について、いろいろなembeddingsがどうなっているかを見ていく。</p><p><img src="/RandomThoughts/assets/0000-DqeMrJZK.png" alt="imgs/OnPositionEmbeddings/0000.png"></p><h2 id="sinusoidal-pe" tabindex="-1"><a class="header-anchor" href="#sinusoidal-pe"><span>Sinusoidal PE</span></a></h2><p>Trans InvとSymmetryは解析的に示せる。</p><p><img src="/RandomThoughts/assets/0001-DmXEOlgS.png" alt="imgs/OnPositionEmbeddings/0001.png"></p><p>Monotonicityは一般には近い所でしか成り立っていない。</p><h2 id="identical-word-probing" tabindex="-1"><a class="header-anchor" href="#identical-word-probing"><span>Identical Word Probing</span></a></h2><p>入力トークンを全部同じ単語にして、最初のレイヤーのアテンションの重みを計算する。 これをいろいろな単語（ランダムに選んだ300単語）で求めて平均すると単語の影響をならした位置だけの効果が期待出来ると期待して、この値をいろいろ調べる。</p><p>また、この値といろいろなタスクのスコアの相関などを求めたりもしている。</p><h2 id="実証実験" tabindex="-1"><a class="header-anchor" href="#実証実験"><span>実証実験</span></a></h2><p>PEをいろいろ変えて、Huggingfaceをfine tuneして<a href="./SQuAD.html">SQuAD</a>と<a href="./GLUE.html">GLUE</a>を評価している。</p><p>GLUEはFully learnable APE(BERTやConvS2Sなど)が一番良いとか（駄目じゃん）。 SQuADはlearnable sin APEが良いと言っているが結構微妙。</p><h2 id="雑感" tabindex="-1"><a class="header-anchor" href="#雑感"><span>雑感</span></a></h2><p><a href="./WhatDoPositionEmbeddingsLearn.html">WhatDoPositionEmbeddingsLearn</a>よりは実験の設計は知りたい事に近いと思う。 結果を見ると理論的な分析はあんまり説得力が無いなぁ、と思うが、 PEの違いがどのくらいあるのかを見るには良い論文とは思う。</p><p>span predictionはPEが無いとスコアがめちゃ下がるので、PE自体は必要なんだな、と説得はされる。</p>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};